-- Domain 1 pilot: lessons rebuilt around the new slide types (term sets,
-- comparisons, diagrams, a worked calculation and ungraded practice
-- scenarios). Title slides are unchanged; mini-exam questions are untouched.
-- Safe to re-run. The previous content is copied to lesson_content_backup first.

create table if not exists lesson_content_backup (
  lesson_id uuid not null,
  content_blocks jsonb not null,
  backed_up_at timestamptz not null default now(),
  note text
);
alter table lesson_content_backup enable row level security;

insert into lesson_content_backup (lesson_id, content_blocks, note)
select id, content_blocks, 'before Domain 1 pilot rewrite' from lessons
where id in ('c05bc493-3645-4b09-9702-c5e1f12b8a85', '5993adc4-6be7-41da-8954-0d6478ce3cee', 'f1cc6e38-a91f-42b6-a7d5-0dfcd44f9548', 'ef1131a7-9cee-4a84-b6b0-309502a86251', 'c288b889-3bc0-495b-8c88-eca196754299', 'b7c16402-b39e-4067-819f-caf9e1352461', 'e916584e-3a66-4a17-b529-ecb67bea3e77', '3912bee6-1524-4566-9f62-12a7eecbfb41', 'd39a4921-0bdb-4264-9560-31d2008e01fc', 'b1b93fcd-ced3-4da2-bec1-0dfeb533fa56', 'af68478a-c30d-4b46-96bc-3e1e7d5dc72a')
  and not exists (select 1 from lesson_content_backup b where b.lesson_id = lessons.id and b.note = 'before Domain 1 pilot rewrite');

-- The CIA Triad
update lessons set content_blocks = '[{"text": "Why the CIA Triad Matters", "type": "title", "overview": "In this lesson, you''ll learn the three properties that form the foundation of information security - confidentiality, integrity, and availability - plus two related properties, authenticity and non-repudiation, that extend the model. By the end, you''ll be able to look at any security incident and identify exactly which principle it violates.", "examContext": "The CIA triad isn''t just a Domain 1 topic - it''s the lens ISC2 expects you to apply across the entire CBK. When later domains cover access control models, cryptography, or incident response, exam questions frequently ask which triad property a given control protects. Expect several questions across the exam that either name confidentiality, integrity, or availability directly, or describe a scenario and ask you to identify which one was violated - plus at least one question on the extended properties, authenticity and non-repudiation. Because this vocabulary underlies question stems throughout the CBK, it''s worth over-learning early: if you can instantly classify any control or incident by which property it protects, you''ll move faster on scenario questions in every other domain."}, {"type": "term_set", "heading": "The CIA triad", "terms": [{"term": "Confidentiality", "short": "Only authorized people can see it.", "mark": "C"}, {"term": "Integrity", "short": "It hasn''t been changed without authorization.", "mark": "I"}, {"term": "Availability", "short": "It''s there when authorized people need it.", "mark": "A"}], "intro": "Nearly every security control exists to protect one or more of these three properties. When a question asks which principle was violated, it''s almost always asking you to pick one of them.", "diagram": {"kind": "triad", "points": [{"label": "Confidentiality"}, {"label": "Integrity"}, {"label": "Availability"}], "center": "protect ≥ 1"}}, {"type": "key_term", "term": "Confidentiality", "definition": "Preventing unauthorized **disclosure** of information. Enforced through principles like need-to-know and least privilege, and controls like encryption and role-based access.", "example": "A laptop holding unencrypted customer records is stolen from a car. Nothing was changed and the system never went down, but the data is now exposed: a confidentiality failure."}, {"type": "key_term", "term": "Integrity", "definition": "Protecting data and systems from unauthorized **modification**, so information stays accurate and trustworthy. Enforced through controls like change management, hashing, and digital signatures.", "example": "An attacker alters payment amounts while transactions are in transit. Even if nobody read the data, it can no longer be trusted: an integrity failure."}, {"type": "key_term", "term": "Availability", "definition": "Ensuring authorized users can **access** systems and data when they need to. Enforced through controls like redundancy, backups, and disaster recovery planning.", "example": "A DDoS attack takes the company website offline for six hours. No data was exposed or changed, but customers couldn''t reach it: an availability failure."}, {"type": "term_set", "heading": "Beyond the core three", "terms": [{"term": "Authenticity", "short": "Proving an identity, message, or asset is genuine. A forged email from the \"CEO\" is an authenticity failure."}, {"term": "Non-repudiation", "short": "Preventing someone from credibly denying an action they took, typically through audit logs and digital signatures."}], "intro": "Two related properties extend the triad and show up regularly on the exam."}, {"type": "compare", "heading": "Which control protects what", "columns": ["Confidentiality", "Integrity", "Availability"], "rows": [{"label": "Typical controls", "values": ["Encryption, access control, need-to-know", "Hashing, digital signatures, change management", "Redundancy, backups, DR planning"]}, {"label": "Typical attack", "values": ["Data theft, eavesdropping, shoulder surfing", "Tampering, man-in-the-middle alteration", "DDoS, ransomware, hardware failure"]}, {"label": "Opposite", "values": ["Disclosure", "Alteration", "Destruction or denial"]}], "cue": ["\"exposed\", \"leaked\", \"viewed\"", "\"altered\", \"modified\", \"tampered\"", "\"offline\", \"unreachable\", \"outage\""], "intro": "The exam often describes the effect and expects you to work backwards to the property. The bottom row is the language to listen for."}, {"type": "scenario", "prompt": "A database administrator quietly changes salary figures in the payroll system before resigning. No records leave the company and the system stays online. Which security principle was **primarily** violated?", "choices": [{"id": "a", "text": "Confidentiality"}, {"id": "b", "text": "Integrity"}, {"id": "c", "text": "Availability"}, {"id": "d", "text": "Non-repudiation"}], "answer": "b", "why": "The data was altered without authorization. Read for the **effect** of the incident, not who did it or how.", "trap": "\"Administrator\" and \"insider\" pull you toward access control and confidentiality, but nothing was disclosed. The admin already had legitimate access to see the data."}, {"type": "scenario", "prompt": "Ransomware encrypts a hospital''s patient records. The attackers never copied the data off the network. What is the **most direct** impact?", "choices": [{"id": "a", "text": "Loss of confidentiality"}, {"id": "b", "text": "Loss of integrity"}, {"id": "c", "text": "Loss of availability"}, {"id": "d", "text": "Loss of authenticity"}], "answer": "c", "why": "Staff can no longer reach the records they need: availability. The data still exists and wasn''t read by the attacker.", "trap": "Encryption is normally a confidentiality control, so seeing \"encrypts\" can mislead you. Here it''s being used as a weapon against availability."}, {"type": "callout", "variant": "tip", "text": "Read for the **effect** of the attack: data exposed (confidentiality), data changed (integrity), system or data unreachable (availability). The attack method is usually a distraction."}]'::jsonb where id = 'c05bc493-3645-4b09-9702-c5e1f12b8a85';

-- Security Governance: Policies, Standards, Procedures, and Guidelines
update lessons set content_blocks = '[{"text": "How Security Documentation Fits Together", "type": "title", "overview": "In this lesson, you''ll learn the governance document hierarchy organizations use to translate high-level security intent into enforceable practice: policies, standards, procedures, baselines, and guidelines. By the end, you''ll be able to tell which of these documents is which, and which ones are mandatory versus optional.", "examContext": "This governance hierarchy shows up as its own standalone questions in Domain 1, but it also frames how the exam expects you to think about every control covered later - CISSP consistently distinguishes between a policy-level requirement and its supporting standard, procedure, or baseline when describing an organization''s controls. Expect a handful of direct \"which document is this\" questions, plus governance framing folded into Domain 1''s broader compliance and legal material. The one fact test-writers lean on most: guidelines are the only non-mandatory document in the hierarchy - that distinction alone accounts for a disproportionate share of missed questions on this topic."}, {"type": "diagram", "heading": "The governance hierarchy", "diagram": {"kind": "pyramid", "tiers": [{"label": "Policy", "note": "Management''s high-level goal. Approved at the executive or board level. Mandatory."}, {"label": "Standards and baselines", "note": "Standards name the specific required technology; baselines set the minimum acceptable configuration. Both mandatory."}, {"label": "Procedures", "note": "Step-by-step instructions for carrying out a standard. Mandatory."}, {"label": "Guidelines", "note": "Recommended best practice. Optional, and not something an auditor can cite you for.", "muted": true}], "top": "broad · sets direction", "bottom": "specific · day to day"}, "caption": "Security governance runs top-down: a broad **policy** sets direction, and every document below it turns that direction into something people and systems can actually follow."}, {"type": "key_term", "term": "Policy", "definition": "A high-level statement of management''s goals and expectations for protecting organizational assets. Approved at the executive or board level. **Mandatory.**", "example": "\"All endpoints must run anti-malware protection.\" It says what must be true, not which product or how to install it."}, {"type": "compare", "heading": "Standard, baseline, procedure", "columns": ["Standard", "Baseline", "Procedure"], "rows": [{"label": "Answers", "values": ["Which technology?", "What''s the minimum setting?", "How exactly do I do it?"]}, {"label": "Example", "values": ["\"The approved anti-malware product is Vendor X.\"", "\"Real-time scanning must be enabled.\"", "The exact install and configuration steps."]}, {"label": "Mandatory?", "values": ["Yes", "Yes", "Yes"]}], "cue": ["names a product or algorithm", "\"minimum\", \"reference configuration\"", "\"step-by-step\", numbered instructions"], "intro": "All three sit under a policy and all three are mandatory. They differ in how specific they are."}, {"type": "key_term", "term": "Guideline", "definition": "A recommended, flexible best practice. It is **not mandatory**, and not something an auditor can cite you for failing to follow.", "example": "\"Consider enabling heuristic scanning on high-risk workstations.\" Helpful advice, but nobody is out of compliance for skipping it."}, {"type": "scenario", "prompt": "A document from the security team reads: \"Administrators should consider enabling multi-factor authentication on internal test servers where practical.\" What type of document is this?", "choices": [{"id": "a", "text": "Policy"}, {"id": "b", "text": "Standard"}, {"id": "c", "text": "Procedure"}, {"id": "d", "text": "Guideline"}], "answer": "d", "why": "\"Should consider\" and \"where practical\" make it optional advice. Guidelines are the only non-mandatory document in the hierarchy.", "trap": "MFA sounds like a technical requirement, which pulls you toward standard. Read the wording, not the topic: a standard would say \"must\"."}, {"type": "scenario", "prompt": "The board approves the statement \"All remote access to company systems must be protected by strong authentication.\" What is this?", "choices": [{"id": "a", "text": "Policy"}, {"id": "b", "text": "Standard"}, {"id": "c", "text": "Baseline"}, {"id": "d", "text": "Procedure"}], "answer": "a", "why": "It''s a high-level, board-approved statement of intent that doesn''t name a product or a configuration. That''s a policy.", "trap": "\"Must\" is mandatory language, but standards, baselines and procedures are mandatory too. The tell is how broad it is and who approved it."}, {"type": "callout", "variant": "tip", "text": "Fastest way to spot the odd one out: policies, standards, baselines and procedures are all **mandatory**. **Guidelines are the only optional one.**"}]'::jsonb where id = '5993adc4-6be7-41da-8954-0d6478ce3cee';

-- Risk Management Fundamentals
update lessons set content_blocks = '[{"text": "Identifying, Assessing, and Treating Risk", "type": "title", "overview": "In this lesson, you''ll learn the core vocabulary of risk management - asset, threat, vulnerability, and risk - along with the four strategies organizations use to treat risk, and how to calculate risk in dollar terms using SLE, ARO, and ALE. By the end, you''ll be able to classify a risk scenario and choose, or calculate, the right response.", "examContext": "Risk management is arguably Domain 1''s center of gravity - it''s the domain''s largest sub-topic, and the concepts here (asset, threat, vulnerability, risk, and the four treatment strategies) recur as vocabulary throughout the rest of the CBK, especially in security assessment and security operations material later in the course. Quantitative risk analysis - SLE, ARO, and ALE - is one of the few places the exam asks you to do arithmetic, and it shows up reliably enough that skipping the math is a common, avoidable point of failure. Expect both straightforward calculation questions and scenario questions asking you to pick the correct treatment strategy - avoid, mitigate, transfer, or accept - for a described situation."}, {"type": "term_set", "heading": "The language of risk", "terms": [{"term": "Asset", "short": "Anything of value that needs protecting: data, systems, people, reputation."}, {"term": "Threat", "short": "Any potential danger that could exploit a vulnerability and cause harm."}, {"term": "Vulnerability", "short": "A weakness a threat can exploit: an unpatched system, a weak password policy, an unlocked server room."}, {"term": "Risk", "short": "The likelihood of a threat exploiting a vulnerability, combined with the impact. No matching threat and vulnerability, no risk."}], "intro": "Risk management means identifying and prioritizing risk, then spending resources to bring its likelihood or impact down to an acceptable level."}, {"type": "diagram", "heading": "How the pieces connect", "diagram": {"kind": "flow", "steps": [{"label": "Threat", "note": "A ransomware gang"}, {"label": "exploits a Vulnerability", "note": "An unpatched VPN appliance"}, {"label": "to harm an Asset", "note": "The file server holding customer contracts"}, {"label": "= Risk", "note": "Likelihood × impact of that happening"}]}, "caption": "Remove any link and the risk disappears: patch the VPN and that threat has nothing to exploit."}, {"type": "compare", "heading": "Four ways to treat a risk", "columns": ["Avoid", "Mitigate", "Transfer", "Accept"], "rows": [{"label": "What you do", "values": ["Stop the activity that creates the risk", "Apply controls to reduce likelihood or impact", "Shift the financial impact to someone else", "Formally acknowledge it and take no further action"]}, {"label": "Example", "values": ["Drop a product line that requires storing card data", "Add MFA and patching", "Buy cyber insurance; outsource with contractual liability", "Leave a low-value kiosk unpatched; sign off on the risk"]}, {"label": "When it fits", "values": ["Risk outweighs the benefit of the activity", "Most common default", "Impact is high but likelihood is low", "Treatment would cost more than the possible loss"]}], "cue": ["\"discontinue\", \"stop offering\"", "\"implement a control\"", "\"insurance\", \"contract\", \"third party\"", "\"management signs off\", \"cost exceeds\""]}, {"type": "callout", "variant": "info", "text": "Transferring a risk moves the **financial** impact, not the **accountability**. If an outsourced provider loses your customers'' data, your organization is still accountable to those customers and regulators."}, {"type": "term_set", "heading": "Putting a dollar figure on risk", "terms": [{"term": "Asset value (AV)", "short": "What the asset is worth."}, {"term": "Exposure factor (EF)", "short": "The percentage of that value lost in one incident."}, {"term": "Single loss expectancy (SLE)", "short": "Cost of one occurrence. **SLE = AV × EF**."}, {"term": "Annualized rate of occurrence (ARO)", "short": "How many times a year it''s expected. Once every 4 years is 0.25."}, {"term": "Annualized loss expectancy (ALE)", "short": "Expected yearly loss. **ALE = SLE × ARO**."}], "intro": "Quantitative risk analysis is one of the few places the exam asks you to do arithmetic."}, {"type": "calc", "heading": "Calculate ALE", "kind": "ale", "intro": "A warehouse worth $400,000 sits in a flood zone. A flood would destroy a quarter of it, and one is expected every 4 years. Change the numbers to see how the result moves.", "defaults": {"assetValue": 400000, "exposureFactor": 25, "aro": 0.25}}, {"type": "scenario", "prompt": "A data center worth $2,000,000 would lose 40% of its value in a major fire. Fires like that are expected once every 20 years. What is the ALE?", "choices": [{"id": "a", "text": "$800,000"}, {"id": "b", "text": "$100,000"}, {"id": "c", "text": "$40,000"}, {"id": "d", "text": "$4,000"}], "answer": "c", "why": "SLE = $2,000,000 × 40% = $800,000. ARO = 1 ÷ 20 = 0.05. ALE = $800,000 × 0.05 = **$40,000** a year.", "trap": "$800,000 is the SLE, a common stop-too-early answer. $100,000 comes from multiplying the asset value by 0.05 and skipping the exposure factor."}, {"type": "scenario", "prompt": "A company stores customer credit card numbers only to support an optional \"save my card\" feature that few customers use. The cost of protecting that data now exceeds the feature''s value. Which treatment is **most appropriate**?", "choices": [{"id": "a", "text": "Accept the risk"}, {"id": "b", "text": "Transfer the risk"}, {"id": "c", "text": "Avoid the risk"}, {"id": "d", "text": "Mitigate the risk"}], "answer": "c", "why": "Stopping the activity that creates the risk, here no longer storing card numbers, removes the risk entirely. That''s avoidance.", "trap": "\"Cost exceeds value\" sounds like the cue for acceptance, but acceptance means keeping the activity and living with the risk. When the activity itself isn''t worth it, drop it."}, {"type": "callout", "variant": "tip", "text": "For calculation questions, write the two formulas down first: **SLE = AV × EF** and **ALE = SLE × ARO**. Convert \"once every N years\" to ARO = 1 ÷ N before multiplying."}]'::jsonb where id = 'f1cc6e38-a91f-42b6-a7d5-0dfcd44f9548';

-- Professional Ethics
update lessons set content_blocks = '[{"text": "Professional Ethics", "type": "title", "overview": "You''ll learn the (ISC)2 Code of Ethics: its four canons and the order you resolve conflicts between them, the ethics complaint process that can revoke a certification, and the Internet Activities Board''s classic guidance (RFC 1087) on what counts as unacceptable use of a network - a favorite source for ethics-themed exam scenarios.", "examContext": "Ethics questions are almost always scenario-based: you''re given a workplace dilemma and asked for the **most correct** action under the Code, not just what sounds reasonable. ISC2 specifically tests canon precedence - when two canons seem to conflict, the lower-numbered (earlier-listed) canon wins. Expect a small but consistent handful of ethics questions across the exam, and at least one that expects you to recognize an RFC 1087-style ''unacceptable activity'' from a described scenario."}, {"type": "paragraph", "text": "Every CISSP holder personally agrees to the **(ISC)² Code of Ethics** as a condition of earning and keeping the certification. Violating it can trigger a formal complaint and the loss of the credential, regardless of what an employer''s own policies say."}, {"type": "diagram", "heading": "The four canons, in order of precedence", "diagram": {"kind": "ladder", "rungs": [{"label": "Protect society, the common good, necessary public trust and confidence, and the infrastructure."}, {"label": "Act honorably, honestly, justly, responsibly, and legally."}, {"label": "Provide diligent and competent service to principals.", "note": "Principals are your employer and clients."}, {"label": "Advance and protect the profession."}], "top": "wins any conflict", "bottom": "gives way first"}, "caption": "When two canons seem to conflict, the higher one on this ladder wins. This is the single most-tested ethics concept."}, {"type": "key_term", "term": "Canon precedence", "definition": "When two canons appear to conflict, resolve in favor of the earlier-listed canon. Protecting the public outweighs loyalty to an employer or client.", "example": "Your employer asks you to keep quiet about a flaw in a medical device that could harm patients. Canon 3 (serve your principal) gives way to canon 1 (protect society)."}, {"type": "paragraph", "text": "Anyone, not just other (ISC)² members, can file an **ethics complaint** against a certified professional. Complaints are reviewed by the (ISC)² Ethics Committee, and a substantiated violation can lead to sanctions up to revocation of the certification."}, {"type": "term_set", "heading": "RFC 1087: unacceptable use of the internet", "terms": [{"term": "Unauthorized access", "short": "Seeking to gain unauthorized access to internet resources."}, {"term": "Disruption", "short": "Disrupting the intended use of the internet."}, {"term": "Waste", "short": "Wasting resources (people, capacity, computers) through such actions."}, {"term": "Destroying integrity", "short": "Destroying the integrity of computer-based information."}, {"term": "Compromising privacy", "short": "Compromising the privacy of users."}], "intro": "In 1989 the Internet Activities Board published RFC 1087, defining activities it considers unethical and unacceptable on a network. It still shapes how the exam frames unauthorized use."}, {"type": "scenario", "prompt": "A security consultant discovers that her client is knowingly shipping firmware with a flaw that could disable heart monitors. The client orders her to keep it confidential. Under the (ISC)² Code, what should guide her decision?", "choices": [{"id": "a", "text": "Her duty to provide diligent service to the client"}, {"id": "b", "text": "Her duty to protect society and the public"}, {"id": "c", "text": "Her duty to advance the profession"}, {"id": "d", "text": "The confidentiality clause in her contract"}], "answer": "b", "why": "Canon 1, protecting society, comes before canon 3, serving principals. Public safety outweighs client confidentiality.", "trap": "Serving the client is a genuine ethical duty, which makes it tempting. It''s just lower on the ladder."}, {"type": "scenario", "prompt": "An employee runs a script that floods a shared research network with traffic \"to test its limits,\" slowing it to a crawl for other users. Which RFC 1087 principle is most clearly violated?", "choices": [{"id": "a", "text": "Gaining unauthorized access"}, {"id": "b", "text": "Disrupting the intended use of the internet"}, {"id": "c", "text": "Compromising user privacy"}, {"id": "d", "text": "Destroying the integrity of information"}], "answer": "b", "why": "Nothing was accessed, read or altered. Other users simply couldn''t use the network as intended: disruption, which also wastes resources.", "trap": "\"Unauthorized\" feels right because nobody approved the test, but RFC 1087''s access item is about getting into resources you''re not allowed to reach."}, {"type": "callout", "variant": "info", "text": "Many employers maintain their own code of ethics or acceptable-use policy. A CISSP follows both, but where they genuinely conflict, the **(ISC)² Code takes precedence**, since abiding by it is a condition of holding the certification."}]'::jsonb where id = 'ef1131a7-9cee-4a84-b6b0-309502a86251';

-- Legal, Regulatory, and Compliance Issues
update lessons set content_blocks = '[{"text": "Legal, Regulatory, and Compliance Issues", "type": "title", "overview": "You''ll learn the major categories of law that shape security programs (criminal, civil, and administrative), the four types of intellectual property protection, the key characteristics of major privacy regulations like GDPR and HIPAA, and the difference between due care and due diligence.", "examContext": "This is one of the densest sub-topics in Domain 1. Expect questions that ask you to name the correct category of law for a scenario, identify which IP protection applies to a given asset (a logo vs. source code vs. a secret recipe), recognize a named regulation from its distinguishing feature (GDPR''s 72-hour breach notice, HIPAA''s ''covered entity''), and distinguish due care from due diligence - a classic, frequently-repeated exam pairing."}, {"type": "paragraph", "text": "Security professionals don''t need to practice law, but they do need to recognize which legal framework applies, because it changes the standard of proof, the process, and the consequences."}, {"type": "compare", "heading": "Three categories of law", "columns": ["Criminal", "Civil (tort)", "Administrative"], "rows": [{"label": "Addresses", "values": ["Conduct harmful to society as a whole", "Disputes between private parties", "Rules issued by government agencies to enforce statutes"]}, {"label": "Brought by", "values": ["The government (prosecution)", "The injured party", "The regulating agency"]}, {"label": "Standard of proof", "values": ["**Beyond a reasonable doubt**", "**Preponderance of the evidence**", "Varies by agency"]}, {"label": "Outcome", "values": ["Fines and imprisonment", "Monetary damages, not jail", "Fines, sanctions, license revocation"]}], "cue": ["\"prosecuted\", \"jail\"", "\"sued\", \"damages\"", "\"regulator\", \"agency rule\""]}, {"type": "compare", "heading": "Four types of intellectual property", "columns": ["Trademark", "Copyright", "Patent", "Trade secret"], "rows": [{"label": "Protects", "values": ["Names, logos, symbols that identify a brand", "Original expression: code, writing, art", "A novel, useful invention or process", "Confidential business information"]}, {"label": "How you get it", "values": ["Use and registration", "Automatic on creation", "Application and public disclosure", "By keeping it secret"]}, {"label": "How long", "values": ["As long as it''s used and renewed", "Long term (author''s life plus decades)", "Generally 20 years", "As long as it stays secret"]}], "cue": ["logo, slogan, product name", "source code, manuals", "\"invention\", \"process\", \"disclose\"", "recipe, formula, algorithm kept private"]}, {"type": "term_set", "heading": "Privacy regulations that come up repeatedly", "terms": [{"term": "GDPR (EU)", "short": "Extraterritorial reach, lawful basis for processing, breach notification within **72 hours**, a \"right to be forgotten\"."}, {"term": "HIPAA (US)", "short": "Health information held by **covered entities** and their **business associates**."}, {"term": "GLBA (US)", "short": "Financial institutions and customer financial data."}, {"term": "SOX (US)", "short": "Financial reporting controls at public companies."}, {"term": "FERPA (US)", "short": "Student education records."}], "intro": "The US has no single federal privacy law, so sector-specific laws fill the gap."}, {"type": "callout", "variant": "info", "text": "Transborder data flow rules restrict where data may physically be stored or processed (data residency or sovereignty). Mechanisms like Standard Contractual Clauses exist to make cross-border transfers, such as EU-to-US, legally defensible."}, {"type": "compare", "heading": "Due diligence vs. due care", "columns": ["Due diligence", "Due care"], "rows": [{"label": "What it is", "values": ["Research and investigation **before** acting", "Reasonable, ongoing **action** to protect assets"]}, {"label": "Memory aid", "values": ["Investigating the alarm system before you buy the house", "Actually arming it every night"]}, {"label": "Example", "values": ["Assessing a vendor''s security before signing", "Patching, monitoring, enforcing policy day to day"]}], "cue": ["\"investigate\", \"assess\", \"research\"", "\"implement\", \"maintain\", \"do\""]}, {"type": "scenario", "prompt": "A company''s competitors can''t figure out the exact blend of spices in its best-selling sauce. The company has never registered it with anyone. Which protection is the company relying on?", "choices": [{"id": "a", "text": "Patent"}, {"id": "b", "text": "Copyright"}, {"id": "c", "text": "Trademark"}, {"id": "d", "text": "Trade secret"}], "answer": "d", "why": "The recipe is protected only because it''s kept confidential. That''s a trade secret, and it lasts as long as the secret does.", "trap": "A recipe feels like an \"invention\", pulling you toward patent, but a patent requires publicly disclosing how it works, which is exactly what this company avoids."}, {"type": "scenario", "prompt": "A security manager reviews a cloud provider''s SOC 2 report and penetration test results before the company signs the contract. What is the manager demonstrating?", "choices": [{"id": "a", "text": "Due care"}, {"id": "b", "text": "Due diligence"}, {"id": "c", "text": "Risk acceptance"}, {"id": "d", "text": "Risk transference"}], "answer": "b", "why": "Investigating before acting is due diligence. Once the contract is signed, operating the controls day to day would be due care.", "trap": "Signing with a cloud provider can also transfer some risk, but the question asks what the manager''s review demonstrates."}, {"type": "callout", "variant": "tip", "text": "Two pairs the exam loves: **criminal vs. civil** (beyond a reasonable doubt vs. preponderance of the evidence) and **due diligence vs. due care** (investigate vs. act)."}]'::jsonb where id = 'c288b889-3bc0-495b-8c88-eca196754299';

-- Understanding Investigation Types
update lessons set content_blocks = '[{"text": "Understanding Investigation Types", "type": "title", "overview": "You''ll learn the four types of investigations a security professional may be pulled into, how the standard of proof and process differ between them, and the evidence-handling fundamentals - chain of custody, the best evidence rule, and the four types of evidence - that determine whether what you collect can actually be used.", "examContext": "Exam questions typically describe a scenario (an employee policy violation vs. a suspected crime vs. a lawsuit) and ask you to identify the correct investigation type, or describe a break in evidence handling and ask what principle was violated. Chain of custody and the best evidence rule are especially high-yield, recurring concepts."}, {"type": "paragraph", "text": "When a security incident happens, how it gets investigated, and by whom, depends on the goal. Misidentifying the type can mean evidence that should have been preserved for court is mishandled instead."}, {"type": "compare", "heading": "Four types of investigations", "columns": ["Administrative", "Criminal", "Civil", "Regulatory"], "rows": [{"label": "Goal", "values": ["Internal action on a policy violation", "Prosecution", "Damages or other relief between private parties", "Enforcing a specific regulation"]}, {"label": "Run by", "values": ["HR or internal security", "Law enforcement", "The parties and their counsel", "A government agency"]}, {"label": "Standard of proof", "values": ["Lowest", "**Beyond a reasonable doubt**", "**Preponderance of the evidence**", "Varies by agency"]}], "cue": ["\"policy\", \"HR\", \"termination\"", "\"law enforcement\", \"prosecute\"", "\"lawsuit\", \"sue\"", "\"agency\", \"regulator\""]}, {"type": "key_term", "term": "Chain of custody", "definition": "A documented, unbroken record of who collected a piece of evidence and everyone who later handled, stored, or transferred it, from collection through presentation in court. A gap can get evidence excluded entirely, regardless of what it shows.", "example": "An analyst images a laptop''s drive, then leaves the image on an unlocked shared drive overnight before logging the handoff. Even if nothing was touched, the defense can now argue it might have been."}, {"type": "diagram", "heading": "The evidence life cycle", "diagram": {"kind": "flow", "steps": [{"label": "Collect"}, {"label": "Identify and tag"}, {"label": "Store and preserve"}, {"label": "Transport"}, {"label": "Present"}, {"label": "Return or destroy"}]}, "caption": "Every handoff along this path has to be logged to preserve the chain of custody."}, {"type": "term_set", "heading": "Four types of evidence", "terms": [{"term": "Real", "short": "Tangible, physical objects: a hard drive, a weapon."}, {"term": "Documentary", "short": "Written records or logs. Must be authenticated and is subject to the best evidence rule."}, {"term": "Testimonial", "short": "Statements made by a witness, subject to the witness''s competency to testify."}, {"term": "Demonstrative", "short": "Helps illustrate other evidence, like a chart or diagram, rather than standing on its own."}]}, {"type": "callout", "variant": "info", "text": "The **best evidence rule** prefers an original document or object over a copy. A duplicate is acceptable only when the original is genuinely unavailable, and not through the fault of the party presenting the copy."}, {"type": "scenario", "prompt": "HR discovers an employee has been using a company laptop to run a personal side business, against acceptable-use policy. The company wants to decide whether to terminate the employee. What type of investigation is this?", "choices": [{"id": "a", "text": "Criminal"}, {"id": "b", "text": "Civil"}, {"id": "c", "text": "Administrative"}, {"id": "d", "text": "Regulatory"}], "answer": "c", "why": "It''s an internal policy violation aimed at internal action like termination. That''s administrative, with the lowest standard of proof.", "trap": "Misusing company property can sound like a crime, but nothing here involves law enforcement or prosecution."}, {"type": "scenario", "prompt": "During a lawsuit, a company presents a printed copy of an email even though the original server log still exists and is available. Which principle does the opposing counsel invoke?", "choices": [{"id": "a", "text": "Chain of custody"}, {"id": "b", "text": "Best evidence rule"}, {"id": "c", "text": "Hearsay rule"}, {"id": "d", "text": "Exclusionary rule"}], "answer": "b", "why": "The original is available, so the best evidence rule prefers it over the copy.", "trap": "Chain of custody is about who handled evidence; here the problem is presenting a copy when the original exists."}, {"type": "callout", "variant": "tip", "text": "High-yield pair: **chain of custody** (who handled it, unbroken) vs. **best evidence rule** (original beats copy)."}]'::jsonb where id = 'b7c16402-b39e-4067-819f-caf9e1352461';

-- Business Continuity & Disaster Recovery Planning
update lessons set content_blocks = '[{"text": "Business Continuity & Disaster Recovery Planning", "type": "title", "overview": "You''ll learn the difference between a Business Continuity Plan and a Disaster Recovery Plan, the Business Impact Analysis that has to happen before either can be built, the four key recovery metrics (MTD, RTO, RPO, WRT) and how they relate to each other, and the three tiers of alternate recovery sites.", "examContext": "This is one of the most numerically-tested topics in Domain 1. Expect questions that give you two of the four metrics and ask about the relationship between them (RTO + WRT must fit within MTD), scenario questions asking you to match a described alternate site to hot/warm/cold, and at least one question testing that BIA always comes before strategy or plan development."}, {"type": "compare", "heading": "BCP vs. DRP", "columns": ["Business Continuity Plan (BCP)", "Disaster Recovery Plan (DRP)"], "rows": [{"label": "Focus", "values": ["Keeping critical **business functions** running during and after a disruption", "Restoring **IT infrastructure and systems**"]}, {"label": "Scope", "values": ["People, processes, facilities, suppliers and IT", "A subset of the BCP"]}, {"label": "Relationship", "values": ["The umbrella", "Every DRP supports a BCP"]}]}, {"type": "key_term", "term": "Business Impact Analysis (BIA)", "definition": "The mandatory first analysis in BCP. It identifies critical business functions and quantifies the impact of losing each one over time. Every later metric and decision flows from it.", "example": "A BIA finds that online order processing costs $50,000 an hour when down, while the internal wiki costs almost nothing. That''s why orders get a hot site and the wiki doesn''t."}, {"type": "diagram", "heading": "The four recovery metrics on one timeline", "diagram": {"kind": "timeline", "event": "Disaster", "before": {"label": "RPO", "note": "Maximum acceptable data loss, measured backwards in time to the last good backup. Drives backup frequency."}, "after": [{"label": "RTO", "note": "Target time to restore the system."}, {"label": "WRT", "note": "Time to verify data and get the business process working again after systems are restored."}], "total": {"label": "MTD", "note": "Maximum tolerable downtime: the longest the function can be down before the harm is unacceptable."}}, "caption": "RPO looks back from the disaster; RTO, WRT and MTD look forward."}, {"type": "callout", "variant": "info", "text": "The classic exam relationship: **RTO + WRT ≤ MTD**. Systems being back online (RTO) isn''t the same as the business function working again (WRT). Both have to fit inside the window the organization can tolerate."}, {"type": "diagram", "heading": "The BCP cycle", "diagram": {"kind": "cycle", "steps": [{"label": "Project scope and initiation"}, {"label": "Business impact analysis"}, {"label": "Recovery strategy"}, {"label": "Plan development"}, {"label": "Testing and exercises"}, {"label": "Maintenance and review"}], "center": "never finished"}, "caption": "It''s a cycle, not a one-time document. The BIA always comes before strategy or plan development."}, {"type": "compare", "heading": "Alternate site strategies", "columns": ["Hot site", "Warm site", "Cold site"], "rows": [{"label": "What''s there", "values": ["Fully configured and staffed", "Some hardware; data must be restored", "Power, space and connectivity only"]}, {"label": "Time to operate", "values": ["Near-immediate", "Hours to about a day", "Days to weeks"]}, {"label": "Cost", "values": ["Highest", "Moderate", "Lowest"]}], "cue": ["\"immediate failover\", \"minutes\"", "\"some equipment\", \"restore backups\"", "\"empty facility\", \"cheapest\""]}, {"type": "key_term", "term": "Reciprocal agreement", "definition": "A mutual-aid arrangement between two organizations with similar infrastructure to host each other during a disaster. Inexpensive, but risky: if both are hit by the same regional disaster, capacity and enforceability become unreliable.", "example": "Two hospitals across town agree to host each other''s systems. A citywide flood takes out both."}, {"type": "scenario", "prompt": "A payroll system has an MTD of 72 hours. Restoring the servers takes 48 hours, and staff then need 30 hours to verify data and reprocess pending pay runs. What''s the problem?", "choices": [{"id": "a", "text": "The RPO is too long"}, {"id": "b", "text": "RTO + WRT exceeds the MTD"}, {"id": "c", "text": "The RTO exceeds the MTD"}, {"id": "d", "text": "There is no problem"}], "answer": "b", "why": "48 hours (RTO) + 30 hours (WRT) = 78 hours, which is more than the 72-hour MTD. The function isn''t back in time even though the servers are.", "trap": "On its own the 48-hour RTO fits inside 72 hours, which is why \"no problem\" is tempting. The business isn''t working again until WRT is done too."}, {"type": "scenario", "prompt": "A company can afford to lose no more than 15 minutes of transaction data. Which metric does this describe, and what does it drive?", "choices": [{"id": "a", "text": "RTO, which drives how fast servers are restored"}, {"id": "b", "text": "RPO, which drives how often backups or replication run"}, {"id": "c", "text": "MTD, which drives site selection"}, {"id": "d", "text": "WRT, which drives staffing"}], "answer": "b", "why": "Acceptable **data loss** measured in time is the RPO. A 15-minute RPO means backups or replication at least every 15 minutes.", "trap": "Fifteen minutes sounds like a recovery-speed number, pulling you toward RTO. Ask whether it''s about time to restore or about data lost."}, {"type": "callout", "variant": "tip", "text": "Data lost is **RPO**. Time down is **RTO**. Getting the business working again is **WRT**. The hard limit is **MTD**. And the BIA always comes first."}]'::jsonb where id = 'e916584e-3a66-4a17-b529-ecb67bea3e77';

-- Personnel Security Policies and Procedures
update lessons set content_blocks = '[{"text": "Personnel Security Policies and Procedures", "type": "title", "overview": "You''ll learn how organizations manage security risk across the employment lifecycle: pre-employment screening, the fraud-detection controls used during employment (separation of duties, job rotation, mandatory vacation, least privilege), how friendly and unfriendly terminations differ in process, and why third-party personnel need the same scrutiny as employees.", "examContext": "The exam loves to test whether you can tell separation of duties, job rotation, and mandatory vacation apart - they''re often presented as near-identical-sounding scenario options. It also reliably tests the timing rule for unfriendly terminations: access is disabled at or before the notification, never after."}, {"type": "paragraph", "text": "People are consistently the weakest link, not usually through malice, but through mistakes, social engineering, or opportunity. Personnel security formalizes how an organization manages that risk from hiring to departure."}, {"type": "diagram", "heading": "The employment lifecycle", "diagram": {"kind": "flow", "steps": [{"label": "Screen", "note": "Background checks scoped to the role''s sensitivity"}, {"label": "Onboard", "note": "NDA and acceptable-use agreement signed before any access"}, {"label": "Employ", "note": "Fraud-detection controls and access reviews"}, {"label": "Offboard", "note": "Revoke access, recover assets, exit interview"}]}}, {"type": "term_set", "heading": "Fraud-detection controls during employment", "terms": [{"term": "Separation of duties", "short": "Split one critical task across multiple people so no one person can complete or hide fraud alone."}, {"term": "Job rotation", "short": "Move people between roles over time; surfaces fraud left behind and cross-trains staff."}, {"term": "Mandatory vacation", "short": "Require consecutive time off while someone else does the job, often revealing irregularities."}, {"term": "Least privilege", "short": "Give each person only the access their job actually requires."}]}, {"type": "compare", "heading": "The three that sound alike", "columns": ["Separation of duties", "Job rotation", "Mandatory vacation"], "rows": [{"label": "Structure", "values": ["**One task**, many people, **at the same time**", "**One person**, many roles, **over time**", "One person **away**, someone else covers"]}, {"label": "Main purpose", "values": ["Prevent fraud (needs collusion to succeed)", "Detect fraud; cross-training", "Detect fraud"]}, {"label": "Example", "values": ["One clerk creates vendors, another approves payments", "An accountant moves to a new ledger every 6 months", "A trader must take 2 consecutive weeks off"]}], "cue": ["\"no single person\", \"collusion\"", "\"periodically moves\", \"cross-train\"", "\"consecutive days off\", \"someone else performs\""]}, {"type": "compare", "heading": "Friendly vs. unfriendly termination", "columns": ["Friendly", "Unfriendly"], "rows": [{"label": "Examples", "values": ["Resignation, retirement", "Firing for cause, layoff"]}, {"label": "Access", "values": ["Revoked through the standard offboarding checklist", "Disabled **at the same time as or just before** notification"]}, {"label": "Why", "values": ["Low risk of retaliation", "Reduces the window for sabotage or data theft"]}]}, {"type": "paragraph", "text": "Contractors and vendor personnel with system access carry the same risk as employees and should meet equivalent standards: background screening for their access level, signed NDAs, and periodic access reviews."}, {"type": "scenario", "prompt": "An auditor finds that a single accounts-payable clerk can both add a new vendor to the system and approve payments to it. Which control is missing?", "choices": [{"id": "a", "text": "Job rotation"}, {"id": "b", "text": "Mandatory vacation"}, {"id": "c", "text": "Separation of duties"}, {"id": "d", "text": "Least privilege"}], "answer": "c", "why": "One person can complete a critical task end to end. Splitting it so creating vendors and approving payments need different people is separation of duties.", "trap": "Least privilege is close, but the clerk may genuinely need both permissions for the job. The issue is one person holding both halves of the same task."}, {"type": "scenario", "prompt": "A systems administrator is being fired for cause this afternoon. When should their system access be disabled?", "choices": [{"id": "a", "text": "After the meeting, once they''ve left the building"}, {"id": "b", "text": "At the end of the business day"}, {"id": "c", "text": "At the same time as or just before they''re notified"}, {"id": "d", "text": "After HR completes the exit interview"}], "answer": "c", "why": "For an unfriendly termination, access goes at or before notification, never after, so there''s no window for retaliation.", "trap": "Every other option leaves the admin with live access after they know they''re being fired."}, {"type": "callout", "variant": "tip", "text": "Separation of duties = one task, many people, same time. Job rotation = one person, many roles, over time."}]'::jsonb where id = '3912bee6-1524-4566-9f62-12a7eecbfb41';

-- Threat Modeling
update lessons set content_blocks = '[{"text": "Threat Modeling", "type": "title", "overview": "You''ll learn what threat modeling is and why it''s done as early as possible in a system''s design, Microsoft''s STRIDE categories and how each maps onto a CIA-triad-style property, the DREAD scoring model for prioritizing threats, and PASTA''s risk-centric, business-aligned approach.", "examContext": "STRIDE is extremely high-yield: expect several questions describing a specific attack scenario and asking which STRIDE category it belongs to. DREAD and PASTA are usually tested at a definitional level - what each one is for, not deep mechanics. Expect at least one question on why threat modeling should happen during design (''shift left'') rather than after deployment."}, {"type": "paragraph", "text": "Threat modeling identifies potential threats and weaknesses in a system, ideally during **design**, before a line of code is written. Finding a flaw on a whiteboard is dramatically cheaper than finding it in production."}, {"type": "compare", "heading": "STRIDE: Microsoft''s six threat categories", "columns": ["What the attacker does", "Violates", "Example"], "rows": [{"label": "**S**poofing", "values": ["Impersonating someone or something", "Authentication", "Logging in with a stolen session cookie"]}, {"label": "**T**ampering", "values": ["Modifying data or code without authorization", "Integrity", "Changing a price in a web form before submitting"]}, {"label": "**R**epudiation", "values": ["Denying having performed an action", "Non-repudiation", "A user deletes logs, then denies the transfer"]}, {"label": "**I**nformation disclosure", "values": ["Exposing information to unauthorized parties", "Confidentiality", "An error page that reveals database credentials"]}, {"label": "**D**enial of service", "values": ["Degrading or denying service", "Availability", "Flooding an API until it stops responding"]}, {"label": "**E**levation of privilege", "values": ["Gaining capabilities without authorization", "Authorization", "A normal user reaches an admin-only function"]}], "intro": "STRIDE maps almost one-to-one onto the CIA triad plus authenticity, non-repudiation and authorization, reframed as attacker actions."}, {"type": "term_set", "heading": "Other approaches", "terms": [{"term": "DREAD", "short": "Scores threats 1 to 10 on Damage, Reproducibility, Exploitability, Affected users and Discoverability to rank which to fix first."}, {"term": "PASTA", "short": "Process for Attack Simulation and Threat Analysis: a 7-stage, risk-centric method that starts from business objectives and works through to concrete attack scenarios."}, {"term": "Attack trees", "short": "A hierarchical diagram of the paths an attacker could take to reach one specific goal."}, {"term": "Trike", "short": "Defines the risk each stakeholder finds acceptable, then models threats against that baseline."}]}, {"type": "compare", "heading": "Which tool for which job", "columns": ["STRIDE", "DREAD", "PASTA"], "rows": [{"label": "Purpose", "values": ["**Categorize** threats", "**Score and prioritize** threats", "Run a full **risk-centric** analysis"]}, {"label": "Starts from", "values": ["The system''s components and data flows", "A list of identified threats", "Business objectives"]}], "cue": ["\"classify\", \"which category\"", "\"rank\", \"score\", \"prioritize\"", "\"business objectives\", \"7 stages\""]}, {"type": "scenario", "prompt": "An attacker modifies the hidden price field in an online store''s checkout form so a $900 laptop is submitted at $9. Which STRIDE category does this fall under?", "choices": [{"id": "a", "text": "Spoofing"}, {"id": "b", "text": "Tampering"}, {"id": "c", "text": "Information disclosure"}, {"id": "d", "text": "Elevation of privilege"}], "answer": "b", "why": "Data was modified without authorization: tampering, which violates integrity.", "trap": "Getting a discount you''re not entitled to can feel like gaining privileges, but the attacker''s permissions never changed. They changed data."}, {"type": "scenario", "prompt": "A team has a list of 40 identified threats and needs to decide which to address first, based on damage, how easy each is to reproduce and exploit, and how many users are affected. Which model fits?", "choices": [{"id": "a", "text": "STRIDE"}, {"id": "b", "text": "DREAD"}, {"id": "c", "text": "PASTA"}, {"id": "d", "text": "Attack tree"}], "answer": "b", "why": "Scoring and ranking threats on those factors is exactly what DREAD is for. The question even lists its letters.", "trap": "STRIDE is the best-known name, but it categorizes threats rather than prioritizing them."}, {"type": "callout", "variant": "tip", "text": "Threat modeling isn''t a one-time gate. Mature programs revisit it throughout the SDLC as the design and attack surface change."}]'::jsonb where id = 'd39a4921-0bdb-4264-9560-31d2008e01fc';

-- Supply Chain Risk Management
update lessons set content_blocks = '[{"text": "Supply Chain Risk Management", "type": "title", "overview": "You''ll learn where supply chain risk comes from (hardware, software, and service providers), what a Software Bill of Materials (SBOM) is and why it matters when a vulnerability is disclosed, and how organizations manage third-party risk through vendor assessment, contractual controls, and ongoing monitoring rather than a one-time check.", "examContext": "Expect scenario questions describing a compromised vendor update mechanism or counterfeit hardware and asking you to recognize it as a supply chain attack, at least one question on what an SBOM is for, and questions testing that vendor risk management is continuous, not a one-time gate at onboarding."}, {"type": "paragraph", "text": "Modern organizations depend on large networks of suppliers, vendors and service providers. A compromise anywhere in that chain can compromise the organization, even when its own systems are perfectly secure."}, {"type": "term_set", "heading": "Where supply chain risk comes from", "terms": [{"term": "Hardware", "short": "Counterfeit or deliberately tampered components introduced during manufacturing or shipping."}, {"term": "Software", "short": "Malicious code inserted into a trusted update mechanism, or hidden in a widely used open-source dependency."}, {"term": "Services", "short": "A third-party provider suffering its own breach and exposing data the organization entrusted to it."}]}, {"type": "diagram", "heading": "How a trusted update becomes an attack", "diagram": {"kind": "flow", "steps": [{"label": "Attacker compromises the vendor", "note": "Breaks into the build or update server"}, {"label": "Malicious code is signed and shipped", "note": "It looks exactly like a normal update"}, {"label": "Customers install it automatically", "note": "Trust in the vendor is the delivery mechanism"}, {"label": "Every customer is compromised at once"}]}, "caption": "The vendor''s legitimate distribution channel becomes the attack vector."}, {"type": "key_term", "term": "Software Bill of Materials (SBOM)", "definition": "A formal, machine-readable inventory of every component, library and dependency in a piece of software. When a vulnerability is disclosed in a widely used component, an SBOM shows quickly whether, and where, you''re exposed.", "example": "When a critical flaw in a common logging library is announced, a team with SBOMs searches them and finds the 14 affected applications in an hour. A team without them spends weeks finding out."}, {"type": "diagram", "heading": "Managing third-party risk", "diagram": {"kind": "cycle", "steps": [{"label": "Assess before onboarding", "note": "Questionnaires, independent audits, SOC 2 reports"}, {"label": "Contract for it", "note": "SLAs with security requirements, right-to-audit clauses"}, {"label": "Monitor continuously", "note": "Reassess for the life of the relationship"}, {"label": "Offboard cleanly", "note": "Revoke access, retrieve or destroy data"}]}, "caption": "Vendor risk management is continuous, not a one-time check at signing."}, {"type": "scenario", "prompt": "A company learns that a monitoring tool it installed from a reputable vendor shipped a signed update containing a backdoor, affecting thousands of the vendor''s customers. What is this?", "choices": [{"id": "a", "text": "An insider threat"}, {"id": "b", "text": "A supply chain attack"}, {"id": "c", "text": "A zero-day exploit against the company"}, {"id": "d", "text": "A watering hole attack"}], "answer": "b", "why": "The attacker compromised a trusted vendor and used its update mechanism to reach downstream customers. That''s a supply chain attack.", "trap": "A backdoor may well use an unknown flaw, but the defining feature is that trust in the vendor delivered it."}, {"type": "scenario", "prompt": "A new vulnerability is announced in a popular open-source compression library. What would let the security team **most quickly** determine which of its applications are affected?", "choices": [{"id": "a", "text": "A recent penetration test report"}, {"id": "b", "text": "The vendors'' SOC 2 reports"}, {"id": "c", "text": "Software Bills of Materials for its applications"}, {"id": "d", "text": "Its vulnerability scanning schedule"}], "answer": "c", "why": "An SBOM lists every component in each application, so the team can search for the library directly.", "trap": "Scanners help eventually, but they need updated signatures and a scan cycle. The question asks for the fastest answer."}, {"type": "callout", "variant": "tip", "text": "The moment an organization shares data or grants access to a vendor, that vendor''s security posture becomes the organization''s risk too."}]'::jsonb where id = 'b1b93fcd-ced3-4da2-bec1-0dfeb533fa56';

-- Security Awareness, Education, and Training
update lessons set content_blocks = '[{"text": "Security Awareness, Education, and Training", "type": "title", "overview": "You''ll learn to distinguish security awareness, training, and education as three distinct tiers with different audiences and goals, how phishing simulations fit into an awareness program, why awareness has to be continuous rather than a once-a-year event, and what building a genuine security culture actually looks like.", "examContext": "The exam reliably tests the awareness/training/education distinction - expect a scenario naming a specific activity and asking which tier it belongs to. Also expect a question on why continuous reinforcement matters more than a single annual session, and on the purpose of phishing simulations."}, {"type": "paragraph", "text": "Even the strongest technical controls fail if a person clicks the phishing link or reuses a compromised password. A mature program invests in people as deliberately as in technology."}, {"type": "compare", "heading": "Three tiers", "columns": ["Awareness", "Training", "Education"], "rows": [{"label": "Audience", "values": ["Everyone", "People in a specific role", "Security professionals"]}, {"label": "Goal", "values": ["Change everyday behavior", "Teach a skill for the job", "Build deep understanding of principles"]}, {"label": "Example", "values": ["Posters, short videos, phishing simulations", "Secure-coding course for developers", "A degree or the CISSP itself"]}, {"label": "Changes", "values": ["What people **notice**", "What people can **do**", "What people **understand**"]}], "cue": ["\"all employees\", \"recognize\"", "\"role-based\", \"hands-on\"", "\"theory\", \"why\", \"certification\""]}, {"type": "key_term", "term": "Phishing simulation", "definition": "A controlled, simulated phishing campaign an organization runs against its own staff to measure susceptibility, usually paired with immediate, targeted training for anyone who clicks.", "example": "After a simulated \"shared invoice\" email, 18% of staff click. Those people get a two-minute lesson on the spot, and next quarter the click rate is tracked again."}, {"type": "callout", "variant": "info", "text": "Awareness needs **continuous reinforcement**, not one annual session. Rotate topics, measure results (click-through and reporting rates), and adapt content as new threats emerge."}, {"type": "term_set", "heading": "Building a security culture", "terms": [{"term": "Leaders model it", "short": "Executives visibly follow the same rules they ask of everyone."}, {"term": "Reporting is easy and blame-free", "short": "People report suspicious activity quickly when they won''t be punished for it."}, {"term": "Good behavior is recognized", "short": "Reinforce people who report and follow process, not just punish mistakes."}]}, {"type": "scenario", "prompt": "A company requires all developers to complete a two-day hands-on course on preventing injection flaws in the languages they use. Which tier is this?", "choices": [{"id": "a", "text": "Awareness"}, {"id": "b", "text": "Training"}, {"id": "c", "text": "Education"}, {"id": "d", "text": "Certification"}], "answer": "b", "why": "It teaches a specific skill to a specific role so they can do their job securely. That''s training.", "trap": "Security topics for developers can sound advanced enough to be education, but education is about theory and principles, not a role-specific skill."}, {"type": "scenario", "prompt": "An organization runs one 45-minute security awareness session each January, but phishing click rates rise steadily through the year. What''s the best improvement?", "choices": [{"id": "a", "text": "Make the annual session longer"}, {"id": "b", "text": "Replace it with a certification requirement"}, {"id": "c", "text": "Deliver short, continuous awareness activities throughout the year and measure results"}, {"id": "d", "text": "Block all external email"}], "answer": "c", "why": "Awareness fades without reinforcement. Short, frequent activities plus measurement keep behavior current.", "trap": "A longer annual session feels thorough but still leaves 11 months without reinforcement."}, {"type": "callout", "variant": "tip", "text": "Awareness changes what people **notice**, training changes what people can **do**, education changes what people **understand**."}]'::jsonb where id = 'af68478a-c30d-4b46-96bc-3e1e7d5dc72a';
